    const layoutPreferenceKey = 'mfl-workbench-layout-v1';
    function readLayoutPreferences() {
      try {
        const value = JSON.parse(window.localStorage.getItem(layoutPreferenceKey) || '{}');
        return value && typeof value === 'object' ? value : {};
      } catch (_error) {
        return {};
      }
    }
    function saveLayoutPreferences() {
      try {
        window.localStorage.setItem(layoutPreferenceKey, JSON.stringify({
          evidenceOpen: drawerUserPreference,
          shortcutsOpen: sideCardsUserPreference,
          v8View: activeV8View,
        }));
      } catch (_error) {
        // Layout remains fully usable when storage is unavailable.
      }
    }
    const savedLayoutPreferences = readLayoutPreferences();
    let drawerReturnFocus = null;
    let drawerUserPreference = typeof savedLayoutPreferences.evidenceOpen === 'boolean' ? savedLayoutPreferences.evidenceOpen : null;
    let sideCardsUserPreference = savedLayoutPreferences.shortcutsOpen !== false;
    // Chat intentionally wins on first launch. The larger workspace is an explicit view.
    let activeV8View = savedLayoutPreferences.v8View === 'workspace' ? 'workspace' : 'chat';
    let responsiveLayoutMode = '';
    const inlineDrawerQuery = window.matchMedia('(min-width: 960px)');
    const fullWorkbenchQuery = window.matchMedia('(min-width: 1360px)');

    function syncViewportContract() {
      const width = Math.max(0, Math.round(window.visualViewport?.width || window.innerWidth || 0));
      const profile = width >= 1360 ? 'full' : width >= 960 ? 'compact' : 'overlay';
      document.body.dataset.viewportProfile = profile;
      if (viewportProof) {
        const label = profile === 'full'
          ? 'full desktop workspace'
          : profile === 'compact'
            ? 'compact desktop workspace'
            : 'overlay workspace';
        viewportProof.textContent = `Responsive layout: ${label}; ${width}px available. Chat and its primary action remain available; workbench panels use the view menu or an overlay.`;
      }
    }

    function currentResponsiveLayoutMode() {
      if (fullWorkbenchQuery.matches) return 'full';
      if (inlineDrawerQuery.matches) return 'compact';
      return 'overlay';
    }

    function setDrawerOpen(open, panel = '', options = {}) {
      const {manageFocus = true, userInitiated = false} = options;
      const wasOpen = document.body.dataset.drawer === 'open';
      if (userInitiated) {
        drawerUserPreference = Boolean(open);
        saveLayoutPreferences();
      }
      if (open && !wasOpen && manageFocus) drawerReturnFocus = document.activeElement;
      if (!open && wasOpen && manageFocus) {
        const returnTarget = drawerReturnFocus || focusModeButton;
        // Move focus before hiding the drawer from assistive technology.
        if (returnTarget && typeof returnTarget.focus === 'function') {
          returnTarget.focus({preventScroll: true});
        }
        drawerReturnFocus = null;
      }
      document.body.dataset.drawer = open ? 'open' : 'closed';
      const overlayMode = currentResponsiveLayoutMode() === 'overlay';
      document.body.classList.toggle('drawer-modal-open', Boolean(open && overlayMode));
      if (evidenceDrawer) {
        evidenceDrawer.hidden = !open;
        evidenceDrawer.setAttribute('aria-hidden', open ? 'false' : 'true');
      }
      focusModeButton?.setAttribute('aria-expanded', open ? 'true' : 'false');
      if (drawerBackdrop) drawerBackdrop.hidden = !(open && overlayMode);
      if (open && panel) selectDrawerTab(panel);
      if (open && overlayMode && manageFocus) {
        window.setTimeout(() => closeDrawerButton?.focus({preventScroll: true}), 40);
      }
    }

    function setShortcutCardsVisible(visible, {userInitiated = false} = {}) {
      sideCardsUserPreference = Boolean(visible);
      document.body.dataset.shortcuts = visible ? 'open' : 'closed';
      if (workbenchShortcuts) {
        workbenchShortcuts.setAttribute('aria-hidden', visible ? 'false' : 'true');
        workbenchShortcuts.inert = !visible;
      }
      toggleSideCardsButton?.setAttribute('aria-expanded', visible ? 'true' : 'false');
      const label = toggleSideCardsButton?.querySelector('.action-label');
      if (label) label.textContent = visible ? 'Hide shortcuts' : 'Show shortcuts';
      if (userInitiated) {
        saveLayoutPreferences();
        showToast(visible ? 'Shortcut cards shown. Chat resized.' : 'Shortcut cards hidden. Chat expanded.');
      }
    }

    function syncResponsiveLayout({initial = false} = {}) {
      syncViewportContract();
      const nextMode = currentResponsiveLayoutMode();
      const modeChanged = nextMode !== responsiveLayoutMode;
      responsiveLayoutMode = nextMode;
      document.body.dataset.layout = nextMode;

      if (initial) {
        if (activeV8View === 'chat') {
          setShortcutCardsVisible(false, {userInitiated: false});
          setDrawerOpen(false, '', {manageFocus: false});
          return;
        }
        setDrawerOpen(nextMode !== 'overlay' && drawerUserPreference !== false, 'evidence', {manageFocus: false});
        return;
      }
      if (!modeChanged) {
        const open = document.body.dataset.drawer === 'open';
        document.body.classList.toggle('drawer-modal-open', open && nextMode === 'overlay');
        if (drawerBackdrop) drawerBackdrop.hidden = !(open && nextMode === 'overlay');
        return;
      }
      if (nextMode === 'overlay') {
        // Never let a desktop-open drawer suddenly cover the chat after a resize.
        setDrawerOpen(false, '', {manageFocus: false});
      } else {
        // Restore an explicit user preference; otherwise desktop layouts open by default.
        setDrawerOpen(drawerUserPreference !== false, 'evidence', {manageFocus: false});
      }
    }

    function selectDrawerTab(name) {
      const tabs = Array.from(document.querySelectorAll('[data-drawer-tab]'));
      tabs.forEach((button, index) => {
        const active = button.dataset.drawerTab === name;
        if (!button.id) button.id = `drawer-tab-${button.dataset.drawerTab || index}`;
        button.classList.toggle('is-active', active);
        button.setAttribute('aria-selected', active ? 'true' : 'false');
        button.tabIndex = active ? 0 : -1;
      });
      document.querySelectorAll('[data-drawer-panel]').forEach((panel, index) => {
        const tab = tabs.find((button) => button.dataset.drawerTab === panel.dataset.drawerPanel);
        if (!panel.id) panel.id = `drawer-panel-${panel.dataset.drawerPanel || index}-${index}`;
        panel.setAttribute('role', 'tabpanel');
        if (tab) panel.setAttribute('aria-labelledby', tab.id);
        panel.hidden = panel.dataset.drawerPanel !== name;
      });
    }

    function setV8View(view, {userInitiated = false, drawerPanel = ''} = {}) {
      const nextView = view === 'workspace' ? 'workspace' : 'chat';
      activeV8View = nextView;
      document.body.dataset.v8View = nextView;
      if (v8ActiveViewLabel) v8ActiveViewLabel.textContent = nextView === 'workspace' ? 'Workbench' : 'Chat';
      document.querySelectorAll('button[data-v8-view]').forEach((button) => {
        const selected = button.dataset.v8View === nextView;
        button.setAttribute('aria-pressed', selected ? 'true' : 'false');
      });
      if (nextView === 'chat') {
        setShortcutCardsVisible(false, {userInitiated: false});
        setDrawerOpen(false, '', {manageFocus: false});
      } else {
        setShortcutCardsVisible(true, {userInitiated: false});
        setDrawerOpen(true, drawerPanel || 'evidence', {manageFocus: false});
      }
      if (userInitiated) saveLayoutPreferences();
      if (v8ViewMenu) v8ViewMenu.open = false;
    }

    focusModeButton?.addEventListener('click', () => setDrawerOpen(document.body.dataset.drawer !== 'open', '', {userInitiated: true}));
    toggleSideCardsButton?.addEventListener('click', () => setShortcutCardsVisible(document.body.dataset.shortcuts !== 'open', {userInitiated: true}));
    closeDrawerButton?.addEventListener('click', () => setDrawerOpen(false, '', {userInitiated: true}));
    drawerBackdrop?.addEventListener('click', () => setDrawerOpen(false, '', {userInitiated: true}));
    // The body also stores the active view; never bind navigation to its
    // bubbled clicks, which would reset every drawer interaction to Evidence.
    document.querySelectorAll('button[data-v8-view]').forEach((button) => {
      button.addEventListener('click', () => setV8View(button.dataset.v8View, {userInitiated: true}));
    });
    document.querySelectorAll('[data-v8-panel]').forEach((button) => {
      button.addEventListener('click', () => {
        const panel = button.dataset.v8Panel || 'evidence';
        setV8View('workspace', {userInitiated: true, drawerPanel: panel});
        // The drawer's legacy initialization can select its evidence tab during
        // startup. Reassert the requested chat-to-panel handoff after layout.
        window.requestAnimationFrame(() => selectDrawerTab(panel));
      });
    });
    document.querySelectorAll('[data-v8-action]').forEach((button) => {
      button.addEventListener('click', () => {
        if (v8ViewMenu) v8ViewMenu.open = false;
        if (button.dataset.v8Action === 'matter') {
          setV8View('workspace', {userInitiated: true, drawerPanel: 'setup'});
          window.requestAnimationFrame(() => selectDrawerTab('setup'));
        }
        if (button.dataset.v8Action === 'errors') openErrorCenter(button);
        if (button.dataset.v8Action === 'settings') welcomeButton?.click();
      });
    });
    document.querySelectorAll('[data-drawer-tab]').forEach((button) => {
      const activateDrawerTab = () => selectDrawerTab(button.dataset.drawerTab || 'setup');
      // Keep the tab strip dependable for mouse, touch, pen, and keyboard input.
      // Some desktop accessibility layers deliver a completed pointer gesture
      // without a synthetic click. Selection is idempotent, so the normal click
      // remains intact while pointer and mouse activation provide the same safe
      // behavior.
      button.addEventListener('mousedown', activateDrawerTab);
      button.addEventListener('pointerup', activateDrawerTab);
      button.addEventListener('click', activateDrawerTab);
      button.addEventListener('keydown', (event) => {
        if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
        event.preventDefault();
        const tabs = Array.from(document.querySelectorAll('[data-drawer-tab]'));
        const current = Math.max(0, tabs.indexOf(button));
        const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (current + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length;
        selectDrawerTab(tabs[next].dataset.drawerTab || 'setup');
        tabs[next].focus({preventScroll: true});
      });
    });
